<template>
  <section class="workspace-page space-y-8">
    <PageHeader title="Integrations" description="Connect merchant-owned payments and the existing business Calendar bridge. Secret credentials are write-only after saving." />
    <div class="grid gap-10 xl:grid-cols-2">
      <section><div class="flex items-start justify-between gap-4"><div><h2 class="display-face text-2xl font-semibold">PayMongo</h2><p class="mt-3 max-w-xl text-sm leading-6 text-muted-foreground">Use credentials from this business’s own PayMongo account. PixelCore creates hosted checkout sessions and never pools merchant funds.</p></div><StatusPill :value="paymongo?.configured ? 'active' : 'setup'" /></div><form class="mt-6 space-y-4 border-y bg-card p-5" @submit.prevent="savePayMongo"><div><label class="field-label" for="paymongo-public">Public key</label><Input id="paymongo-public" v-model.trim="paymentForm.public_key" autocomplete="off" /></div><div><label class="field-label" for="paymongo-secret">Secret key</label><Input id="paymongo-secret" v-model="paymentForm.secret_key" type="password" :required="!paymongo?.configured" autocomplete="new-password" placeholder="Leave blank to keep the saved key" /></div><div><label class="field-label" for="paymongo-webhook">Webhook secret</label><Input id="paymongo-webhook" v-model="paymentForm.webhook_secret" type="password" :required="!paymongo?.configured" autocomplete="new-password" placeholder="Leave blank to keep the saved secret" /></div><label class="flex items-start gap-3"><NativeCheckbox v-model="paymentForm.is_live" class="mt-1 h-4 w-4" /><span><span class="block text-sm font-semibold">Live mode</span><span class="mt-1 block text-xs text-muted-foreground">Turn this on only when the saved credentials and webhook are live.</span></span></label><p v-if="paymentMessage" :class="paymentTone" class="text-sm" aria-live="polite">{{ paymentMessage }}</p><Button :disabled="savingPayment">{{ savingPayment ? 'Saving connection…' : 'Save PayMongo connection' }}</Button></form></section>
      <section><div class="flex items-start justify-between gap-4"><div><h2 class="display-face text-2xl font-semibold">Google Calendar</h2><p class="mt-3 max-w-xl text-sm leading-6 text-muted-foreground">Confirmed bookings update the existing business event, which remains the single synchronization bridge.</p></div><StatusPill :value="calendar?.connected ? 'active' : 'setup'" /></div><div class="mt-6 border-y bg-card p-5"><template v-if="calendar?.connected"><p class="font-bold">Connected as {{ calendar.google_email }}</p><p class="mt-2 text-sm text-muted-foreground">Last synchronized {{ calendar.last_synced_at ? formatDate(calendar.last_synced_at) : 'not yet' }}.</p><div class="mt-5 flex flex-wrap gap-2"><Button variant="outline" type="button" @click="syncCalendar">Sync events</Button><Button variant="outline" class="text-destructive" type="button" @click="disconnectCalendar">Disconnect</Button></div></template><template v-else><p v-if="calendar?.configuration_error" role="alert" class="text-sm text-destructive">{{ calendar.configuration_error }}</p><ButtonAnchor  v-else-if="calendar?.authorize_url" :href="calendar.authorize_url">Connect Google Calendar</ButtonAnchor><p v-else class="text-sm text-muted-foreground">Calendar connection is not configured on this server.</p></template><p v-if="calendarMessage" class="mt-4 text-sm" aria-live="polite">{{ calendarMessage }}</p></div></section>
    </div>
  </section>
</template>

<script setup>
const business = useBusinessStore(); const { apiFetch } = useApiClient(); const paymongo = ref(null); const calendar = ref(null); const paymentForm = reactive({ public_key: '', secret_key: '', webhook_secret: '', is_live: false, is_active: true }); const savingPayment = ref(false); const paymentMessage = ref(''); const paymentTone = ref('text-muted-foreground'); const calendarMessage = ref('')
onMounted(async () => { if (!business.activeBusiness) await business.loadBusinesses(); await load() })
async function load() { if (!business.activeBusiness) return; const id = business.activeBusiness.public_id; const [connections, calendarResponse] = await Promise.all([apiFetch(`businesses/${id}/payments/connections/`).catch(() => []), apiFetch(`businesses/${id}/google-calendar/`).catch(() => null)]); paymongo.value = connections.find((item) => item.provider === 'paymongo') || null; calendar.value = calendarResponse; if (paymongo.value) Object.assign(paymentForm, { public_key: paymongo.value.public_key, is_live: paymongo.value.is_live, is_active: paymongo.value.is_active }) }
async function savePayMongo() { savingPayment.value = true; paymentMessage.value = ''; try { const body = { ...paymentForm }; if (!body.secret_key) delete body.secret_key; if (!body.webhook_secret) delete body.webhook_secret; paymongo.value = await apiFetch(`businesses/${business.activeBusiness.public_id}/payments/connections/paymongo/`, { method: 'PUT', body }); paymentForm.secret_key = ''; paymentForm.webhook_secret = ''; paymentMessage.value = 'PayMongo connection saved. Configure the generated business webhook URL in PayMongo.'; paymentTone.value = 'text-primary' } catch (error) { paymentMessage.value = error?.data?.error?.message || 'The PayMongo connection could not be saved.'; paymentTone.value = 'text-destructive' } finally { savingPayment.value = false } }
async function syncCalendar() { calendarMessage.value = 'Synchronizing…'; try { const response = await apiFetch(`businesses/${business.activeBusiness.public_id}/google-calendar/sync/`, { method: 'POST' }); calendarMessage.value = `${response.synced} of ${response.total} events synchronized.`; await load() } catch { calendarMessage.value = 'Calendar synchronization failed. Review the connection and try again.' } }
async function disconnectCalendar() { if (!window.confirm('Disconnect Google Calendar for this business? Existing PixelCore events will remain.')) return; await apiFetch(`businesses/${business.activeBusiness.public_id}/google-calendar/`, { method: 'DELETE' }); await load() }
const formatDate = (value) => new Intl.DateTimeFormat('en-PH', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value))
</script>
